import numpy as np, math, compressed_layer as cl
full = dict(delegate=True, structured=True, pcs=True, batch_trace=True, batch_ub=True, batch_wiring=True, commit_base=True)
ns=list(range(8,19,2)); D={}
for n in ns:
    x=(1<<n)-1
    r=cl.run_chain(x, np.random.default_rng(1), **full)
    D[n]=r
def fit(key):
    pts=ns[-4:]
    return cl._fit_slope(pts,[math.log2(max(1,D[n][key])) for n in pts])
for key in ['comm','comm_outer','comm_bw','comm_base','comm_bt']:
    print(f'{key:12s} alpha={fit(key):.3f}')
tv=lambda n: D[n]['vleaf_ops_pl']+D[n]['vleaf_ops_ot']
print('verifier_ops alpha=%.3f'%cl._fit_slope(ns[-4:],[math.log2(tv(n)) for n in ns[-4:]]))
"

